/**
 * Medieval clothing and armour, generated by this project (MIT): the pieces the
 * MakeHuman asset packs don't have (tunics, jerkin, gambeson, mail, plate,
 * mantle, hose, belt). They are built from base-mesh helpers, so they follow every
 * body morph and the skeleton:
 *
 * - bodices and sleeves are cut from the "tights" helper (like garments.ts),
 * - hanging parts (tunic and hauberk skirts, surcoat) are cut from the
 *   "skirt" helper, a long skirt that is part of the base mesh,
 * - the mail coif is cut from the head and neck skin.
 *
 * Armour plates and the coif are pushed out to a smooth convex "envelope" of
 * the body (convex hull per horizontal slice), so they don't show the
 * muscles or the breasts underneath. Garments with a hanging part use skirt
 * skinning (`legBlend`) and the leg colliders.
 */
import type { MeshDef, ProxyDef } from "@actors/core";
import type { GarmentInfo } from "@actors/human";
import { BlobWriter } from "./blob";
import {
  type Fabric,
  type GarmentContext,
  IN,
  OUT,
  type Point,
  armPos,
  garmentCut,
  has,
  insideFaces,
  isArm,
  isLeg,
  legHole,
  legPos,
  neckline,
  selectGarmentFaces,
  sleeve,
} from "./garments";
import type { Vec3 } from "./geometry";
import { GARMENT_LODS, simplifyLevels } from "./lod";
import { type ObjData, type ObjFace, buildRenderMesh } from "./obj";

const min = Math.min, max = Math.max;
const clamp01 = (t: number) => max(0, min(1, t));
const smooth = (t: number) => { const s = clamp01(t); return s * s * (3 - 2 * s); };

/** Meters of garment per UV unit (matches the tights helper's normalized UVs, which set the fabric scale). */
const UV_METERS = 1.669;

/** Convex outline of the body per horizontal slice, as a radius around a vertical axis. */
export class Envelope {
  private readonly radii: Float32Array[] = [];
  constructor(
    positions: number[],
    vertices: number[],
    readonly center: [number, number],
    readonly y0: number,
    readonly y1: number,
    options: { step?: number; bins?: number; dilate?: number; blur?: number; angularBlur?: number; drape?: boolean } = {},
  ) {
    const step = (this.step = options.step ?? 0.01);
    const bins = (this.bins = options.bins ?? 96);
    const slices = Math.max(2, Math.ceil((y1 - y0) / step) + 1);
    const byslice: [number, number][][] = Array.from({ length: slices }, () => []);
    for (const v of vertices) {
      const y = positions[v * 3 + 1];
      const k0 = Math.floor((y - y0) / step - 1.5), k1 = Math.ceil((y - y0) / step + 1.5);
      for (let k = max(0, k0); k <= min(slices - 1, k1); k++)
        if (Math.abs(y0 + k * step - y) <= step * 1.5) byslice[k].push([positions[v * 3] - center[0], positions[v * 3 + 2] - center[1]]);
    }
    let raw = byslice.map((pts) => hullRadii(pts, bins));
    const dilate = options.dilate ?? 2, blur = options.blur ?? 2, ab = blur ? options.angularBlur ?? 1 : 0;
    // Upper envelope: widen over neighbouring slices, then blur (stays at or above the raw outline).
    raw = raw.map((_, k) => {
      const out = new Float32Array(bins);
      for (let j = k - dilate; j <= k + dilate; j++) if (j >= 0 && j < slices) for (let b = 0; b < bins; b++) out[b] = max(out[b], raw[j][b]);
      return out;
    });
    if (options.drape) for (let k = slices - 2; k >= 0; k--) for (let b = 0; b < bins; b++) raw[k][b] = max(raw[k][b], raw[k + 1][b]);
    for (let k = 0; k < slices; k++) {
      const out = new Float32Array(bins);
      for (let b = 0; b < bins; b++) {
        let sum = 0, weight = 0;
        for (let j = -blur * 2; j <= blur * 2; j++)
          for (let a = -ab; a <= ab; a++) {
            const kk = k + j;
            if (kk < 0 || kk >= slices) continue;
            const w = Math.exp(-(j * j) / (2 * blur * blur + 1e-6) - (a * a) / (2 * ab * ab * 0.5 + 1e-6));
            sum += raw[kk][(b + a + bins) % bins] * w;
            weight += w;
          }
        out[b] = sum / weight;
      }
      this.radii.push(out);
    }
  }
  private readonly step: number;
  private readonly bins: number;

  /** Angle around the axis (0 = front, +Z; pi/2 = the body's left, +X). */
  angle(x: number, z: number): number {
    return Math.atan2(x - this.center[0], z - this.center[1]);
  }

  radius(theta: number, y: number): number {
    const fk = clamp01((y - this.y0) / (this.y1 - this.y0)) * (this.radii.length - 1);
    const k = Math.min(this.radii.length - 2, Math.floor(fk)), tk = fk - k;
    const fb = (((theta / (Math.PI * 2)) % 1) + 1) % 1 * this.bins;
    const b = Math.floor(fb) % this.bins, tb = fb - Math.floor(fb), b1 = (b + 1) % this.bins;
    const r = (row: Float32Array) => row[b] * (1 - tb) + row[b1] * tb;
    return r(this.radii[k]) * (1 - tk) + r(this.radii[k + 1]) * tk;
  }

  /** Offset that moves a point out to the envelope (plus `gap`), along the horizontal from the axis; zero if already outside. */
  pushOut(c: { x: number; y: number; z: number }, gap: number, share = 1): Vec3 {
    const dx = c.x - this.center[0], dz = c.z - this.center[1];
    const r = Math.hypot(dx, dz);
    if (r < 1e-4) return [0, 0, 0];
    const target = this.radius(this.angle(c.x, c.z), c.y) + gap;
    const d = max(0, target - r) * share;
    return [(dx / r) * d, 0, (dz / r) * d];
  }
}

/** Radius of a 2D point set's convex hull along `bins` directions from the origin. */
function hullRadii(points: [number, number][], bins: number): Float32Array {
  const out = new Float32Array(bins);
  if (!points.length) return out;
  const pts = points.slice().sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cross = (o: number[], a: number[], b: number[]) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lower: [number, number][] = [], upper: [number, number][] = [];
  for (const p of pts) {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], p) <= 0) lower.pop();
    lower.push(p);
  }
  for (let i = pts.length - 1; i >= 0; i--) {
    const p = pts[i];
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], p) <= 0) upper.pop();
    upper.push(p);
  }
  const hull = lower.slice(0, -1).concat(upper.slice(0, -1));
  for (let b = 0; b < bins; b++) {
    const t = (b / bins) * Math.PI * 2;
    const dx = Math.sin(t), dz = Math.cos(t); // direction in (x, z)
    let best = 0;
    if (hull.length < 3) {
      for (const [x, z] of hull) best = max(best, x * dx + z * dz);
    } else {
      for (let i = 0; i < hull.length; i++) {
        const [ax, az] = hull[i], [bx, bz] = hull[(i + 1) % hull.length];
        // Solve origin + s*d = a + u*(b - a).
        const ex = bx - ax, ez = bz - az;
        const den = dx * ez - dz * ex;
        if (Math.abs(den) < 1e-12) continue;
        const s = (ax * ez - az * ex) / den;
        const u = (ax * dz - az * dx) / den;
        if (u >= -1e-6 && u <= 1 + 1e-6 && s > best) best = s;
      }
    }
    out[b] = best;
  }
  return out;
}

export interface MedievalContext extends GarmentContext {
  obj: ObjData;
  facesOf: (...groups: string[]) => ObjFace[];
  /** Base vertices hidden under a garment surface (see import.ts). */
  coveredBody: (gPos: number[], gFaces: number[][], radius?: number, margin?: number) => number[];
  skirtBlend: NonNullable<ProxyDef["legBlend"]>;
}

type Offset = (c: Point) => Vec3;

interface Piece {
  /** Base-mesh face group the piece is cut from. */
  group: "helper-tights" | "helper-skirt" | "body";
  cut: (c: Point, ctx: GarmentContext) => number;
  offset?: Offset;
  /**
   * Bind to a coarse sample of the body (points this far apart) instead of the vertex itself, so
   * body morphs move the piece but don't print muscles and other small detail into it (plates).
   */
  smoothBind?: number;
  /** Hide the skin under the piece's fully covered faces. */
  hideSkin?: boolean;
  minIsland?: number;
}

export interface MedievalSpec {
  name: string;
  label: string;
  category: "Medieval clothing" | "Medieval armour";
  occupies: string[];
  color: [number, number, number];
  roughness: number;
  fabric: Fabric;
  /** Meters along the normal. */
  inflate: number;
  /** Draw order among garments (see garmentLayer in @actors/three): outer layers get larger values. */
  layer: number;
  /** Skirt skinning: the hanging part swings with both legs and is pushed out by the leg colliders. */
  hangs?: boolean;
  /** Share of leg motion handed to the pelvis (skirt skinning); larger = calmer hem. */
  hipShare?: number;
  hidesHair?: boolean;
  /** Pieces cut from base-mesh helpers. */
  pieces: (m: Landmarks) => Piece[];
}

/** Body measurements the cuts and envelopes are built from (base mesh, meters). */
interface Landmarks {
  ctx: GarmentContext;
  pelvis: number;
  waist: number;
  chest: number;
  neck: number;
  /** Hip joint and ankle heights (skirt hems are fractions of the way down). */
  hip: number;
  ankle: number;
  torso: Envelope;
  /** Torso outline hanging straight down from the chest (surcoats, breastplates). */
  drape: Envelope;
  head: Envelope;
  /** y of the hem at `t` of the way from the hip joint (0) to the ankle (1). */
  hem: (t: number) => number;
}

const skirtTop = (m: Landmarks, c: Point, gap: number, flare: number): Vec3 => {
  // Hanging parts: out over the bodice at the waist, then flaring towards the hem.
  const t = clamp01((m.waist - c.y) / (m.waist - m.ankle));
  const dx = c.x, dz = c.z - m.torso.center[1];
  const r = Math.hypot(dx, dz) || 1;
  const d = gap + flare * t * t;
  return [(dx / r) * d, 0, (dz / r) * d];
};

/** Draped over the chest and clear of the mail on the back and shoulders: the larger of the two push-outs. */
const over = (m: Landmarks, c: Point, gap: number): Vec3 => {
  const a = m.drape.pushOut(c, gap, 1), b = m.torso.pushOut(c, gap - 0.004, 1);
  return Math.hypot(...a) >= Math.hypot(...b) ? a : b;
};

/** Skirt hem at `t` (hip to ankle), with optional slits at the front and back up to `slit`. */
const skirtCut = (m: Landmarks, t: number, slit = 0, slitWidth = 0.03) => (c: Point) => {
  // Starts just under the belt line, over the bodice's hem.
  const hem = min(c.y - m.hem(t), m.pelvis + 0.02 - c.y);
  if (!slit) return hem;
  // Inside the slit (near the centre line, below its top) counts as outside the garment.
  return min(hem, -min(slitWidth - Math.abs(c.x), m.hem(slit) - c.y));
};

const torsoBelow = (m: Landmarks, c: Point, y: number) => (isLeg(c.bone) ? OUT : c.y - y);

/** Bodice with sleeves to `arm` (0 = shoulder, 1 = wrist) and a hem at `hemY`. */
const bodice = (m: Landmarks, arm: number, hemY: number, neck: number) => (c: Point, ctx: GarmentContext) =>
  min(torsoBelow(m, c, hemY), neckline(c, ctx, neck), sleeve(c, ctx, arm));

