/** Face opening of the coif: an oval from the brow to the chin. */
function faceOpening(m: Landmarks & { eyes?: Vec3 }, c: Point): number {
  const e = (m as { eyes: Vec3 }).eyes;
  if (c.z < e[2] - 0.075) return OUT;
  return 1 - Math.hypot(c.x / 0.072, (c.y - (e[1] - 0.035)) / 0.1);
}

export interface MedievalOutput {
  proxies: ProxyDef[];
  meshes: MeshDef[];
  files: { file: string; data: Uint8Array }[];
  labels: Record<string, string>;
  info: Record<string, GarmentInfo>;
}

export function buildMedieval(mc: MedievalContext): MedievalOutput {
  const P = mc.positions;
  const bodyFaces = mc.facesOf("body");
  const bodyVerts = [...new Set(bodyFaces.flatMap((f) => f.v))];
  const torsoBones = (b: string) => has(b, "pelvis", "spine_01", "spine_02", "spine_03", "neck_01", "clavicle");
  const pelvis = mc.joint("pelvis");
  const eyes = [0, 1, 2].map((c) => {
    const vs = [...new Set(mc.facesOf("helper-l-eye", "helper-r-eye").flatMap((f) => f.v))];
    return vs.reduce((s, v) => s + P[v * 3 + c], 0) / vs.length;
  }) as Vec3;
  const neck = mc.joint("neck_01")[1];
  const torso = new Envelope(P, bodyVerts.filter((v) => torsoBones(mc.dominantBone(v))), [0, pelvis[2]], pelvis[1] - 0.1, neck + 0.05, { dilate: 6, blur: 4 });
  const drape = new Envelope(P, bodyVerts.filter((v) => torsoBones(mc.dominantBone(v)) && !has(mc.dominantBone(v), "clavicle")), [0, pelvis[2]], pelvis[1] - 0.1, mc.joint("spine_03")[1] + 0.09, { dilate: 3, blur: 4, drape: true });
  // Head, neck and ears, minus the face (its front is open in the coif).
  const headVerts = bodyVerts.filter((v) => has(mc.dominantBone(v), "head", "neck_01"));
  const headCenterZ = (Math.min(...headVerts.map((v) => P[v * 3 + 2])) + eyes[2]) / 2;
  const hipY = mc.joint("thigh_l")[1], ankleY = mc.joint("foot_l")[1];
  const m: Landmarks & { eyes: Vec3 } = {
    ctx: mc,
    pelvis: pelvis[1],
    waist: mc.joint("spine_01")[1] + 0.03,
    chest: mc.joint("spine_03")[1],
    neck,
    hip: hipY,
    ankle: ankleY,
    torso,
    drape,
    head: undefined as unknown as Envelope,
    hem: (t) => hipY + (ankleY - hipY) * t,
    eyes,
  };
  m.head = new Envelope(
    P,
    headVerts.filter((v) => faceOpening(m, { x: P[v * 3], y: P[v * 3 + 1], z: P[v * 3 + 2], bone: "head" }) < -0.25),
    [0, headCenterZ],
    neck - 0.05,
    eyes[1] + 0.2,
    { dilate: 2, blur: 2 },
  );

  const out: MedievalOutput = { proxies: [], meshes: [], files: [], labels: {}, info: {} };
  for (const spec of MEDIEVAL) {
    const g = fromPieces(mc, spec, spec.pieces(m));
    const writer = new BlobWriter();
    const file = `garments/${spec.name}.bin`;
    const n = g.offsets.length / 3;
    const proxy: ProxyDef = {
      name: spec.name,
      vertexCount: n,
      refs: writer.add("u32", g.refs),
      weights: writer.add("f32", g.weights),
      offsets: writer.add("f32", g.offsets),
      scaleRefs: g.scaleRefs,
      ...(spec.hangs ? { legBlend: { ...mc.skirtBlend, ...(spec.hipShare ? { hipShare: spec.hipShare } : {}) } } : {}),
      blob: file,
    };
    const covers = g.coversAnatomy;
    out.meshes.push({
      name: spec.name,
      source: { kind: "proxy", proxy: spec.name },
      role: "garment",
      optional: true,
      blob: file,
      inflate: spec.inflate,
      material: { kind: "cloth", color: spec.color, roughness: spec.roughness },
      tags: [`fabric:${spec.fabric}`, `layer:${spec.layer}`, ...(covers ? ["covers:anatomy"] : []), ...(spec.hidesHair ? ["covers:hair"] : [])],
      baseIndex: writer.add("u32", g.map),
      uv: writer.add("f32", g.uv),
      indices: writer.add("u32", g.indices),
      ...(g.clip ? { clip: writer.add("f32", g.clip) } : {}),
      simplified: simplifyLevels(writer, g.positions, g, GARMENT_LODS, g.clip),
      ...(g.hides.length ? { hidesBaseVertices: writer.add("u32", g.hides) } : {}),
    });
    out.proxies.push(proxy);
    out.files.push({ file, data: writer.toBuffer() });
    out.labels[spec.name] = spec.label;
    out.info[spec.name] = { label: spec.label, category: spec.category, occupies: spec.occupies, credit: "Actors procedural garment (MIT)" };
  }
  return out;
}

interface Built {
  refs: number[];
  weights: number[];
  offsets: number[];
  /** Fitted positions on the base body (for LODs). */
  positions: number[];
  scaleRefs: ProxyDef["scaleRefs"];
  map: number[];
  uv: number[];
  indices: number[];
  clip?: number[];
  hides: number[];
  coversAnatomy: boolean;
}

/** Each axis' extreme vertices among `vertices`, as proxy scale references. */
function scaleRefsOf(P: number[], vertices: number[]): ProxyDef["scaleRefs"] {
  return [0, 1, 2].map((axis) => {
    let lo = vertices[0], hi = lo;
    for (const v of vertices) {
      if (P[v * 3 + axis] < P[lo * 3 + axis]) lo = v;
      if (P[v * 3 + axis] > P[hi * 3 + axis]) hi = v;
    }
    return [lo, hi, P[hi * 3 + axis] - P[lo * 3 + axis]];
  }) as ProxyDef["scaleRefs"];
}

/** UVs of a base-mesh group, normalized and scaled so a UV unit is `UV_METERS` on the body (consistent fabric scale). */
function groupUV(mc: MedievalContext, group: string): (uv: number[]) => number[] {
  const faces = mc.facesOf(group);
  const { obj, positions: P } = mc;
  let u0 = Infinity, u1 = -Infinity, v0 = Infinity, v1 = -Infinity;
  for (const f of faces) for (const t of f.vt) {
    u0 = min(u0, obj.uvs[t * 2]); u1 = max(u1, obj.uvs[t * 2]);
    v0 = min(v0, obj.uvs[t * 2 + 1]); v1 = max(v1, obj.uvs[t * 2 + 1]);
  }
  const su = 1 / (u1 - u0 || 1), sv = 1 / (v1 - v0 || 1);
  let ratio = 0, count = 0;
  for (const f of faces)
    for (let k = 0; k < f.v.length; k++) {
      const a = f.v[k], b = f.v[(k + 1) % f.v.length], ta = f.vt[k], tb = f.vt[(k + 1) % f.v.length];
      const d = Math.hypot(P[a * 3] - P[b * 3], P[a * 3 + 1] - P[b * 3 + 1], P[a * 3 + 2] - P[b * 3 + 2]);
      const du = Math.hypot((obj.uvs[ta * 2] - obj.uvs[tb * 2]) * su, (obj.uvs[ta * 2 + 1] - obj.uvs[tb * 2 + 1]) * sv);
      if (du > 1e-9) { ratio += d / du; count++; }
    }
  const scale = (count ? ratio / count : UV_METERS) / UV_METERS;
  return (uv) => uv.map((x, i) => (i % 2 ? (x - v0) * sv : (x - u0) * su) * scale);
}

const isTorso = (mc: MedievalContext, v: number) => {
  const b = mc.dominantBone(v);
  return has(b, "clavicle") || !(isArm(b) || isLeg(b) || has(b, "head", "neck"));
};
const torsoSampleCache = new WeakMap<MedievalContext, Map<number, number[]>>();
/** Coarse samples of the torso (from the body suit), shared by every garment with the same spacing. */
function torsoSamples(mc: MedievalContext, spacing: number): number[] {
  const cache = torsoSampleCache.get(mc) ?? new Map<number, number[]>();
  torsoSampleCache.set(mc, cache);
  if (!cache.has(spacing)) {
    const vs = [...new Set(mc.facesOf("helper-tights").flatMap((f) => f.v))].filter((v) => isTorso(mc, v));
    cache.set(spacing, coarseSample(mc.positions, vs, spacing));
  }
  return cache.get(spacing)!;
}

function fromPieces(mc: MedievalContext, spec: MedievalSpec, pieces: Piece[]): Built {
  const P = mc.positions;
  const verts: number[] = [];
  const local = new Map<number, number>();
  const offsets: number[] = [];
  const b: Built = { refs: [], weights: [], offsets, positions: [], scaleRefs: [[0, 0, 0], [0, 0, 0], [0, 0, 0]], map: [], uv: [], indices: [], clip: [], hides: [], coversAnatomy: false };
  const covered: number[][] = [];
  const smoothOf = new Map<number, number>();
  const coarse = new Map<number, number[]>();
  const genitals = [...new Set(mc.facesOf("helper-genital").flatMap((f) => f.v))];
  const gc = [0, 1, 2].map((c) => genitals.reduce((s, v) => s + P[v * 3 + c], 0) / genitals.length);
  for (const piece of pieces) {
    const faces = mc.facesOf(piece.group);
    const cut = garmentCut(faces, piece, mc);
    const sel = selectGarmentFaces(faces, cut, piece.minIsland ?? 40);
    if (!sel.length) throw new Error(`${spec.name}: empty ${piece.group} piece`);
    if (piece.smoothBind) {
      const own = [...new Set(sel.flatMap((f) => f.v))];
      coarse.set(piece.smoothBind, [...(coarse.get(piece.smoothBind) ?? []), ...coarseSample(P, own.filter((v) => !isTorso(mc, v)), piece.smoothBind)]);
      // Sleeves stay bound to their own vertices: layered sleeves must bend alike.
      for (const f of sel) for (const v of f.v) if (!isArm(mc.dominantBone(v)) || has(mc.dominantBone(v), "clavicle") || spec.category === "Medieval armour" && !spec.hangs) smoothOf.set(v, piece.smoothBind);
    }
    const rm = buildRenderMesh(mc.obj, sel);
    const uv = groupUV(mc, piece.group)(rm.uv);
    const start = b.map.length;
    rm.map.forEach((v, i) => {
      if (!local.has(v)) {
        local.set(v, verts.length);
        verts.push(v);
        const o = piece.offset?.({ x: P[v * 3], y: P[v * 3 + 1], z: P[v * 3 + 2], bone: mc.dominantBone(v) }) ?? [0, 0, 0];
        offsets.push(...o);
        b.positions.push(...o.map((d, axis) => P[v * 3 + axis] + d));
      }
      b.map.push(local.get(v)!);
      b.clip!.push(cut.get(v)!);
      b.uv.push(uv[i * 2], uv[i * 2 + 1]);
    });
    for (const i of rm.indices) b.indices.push(start + i);
    const inside = insideFaces(sel, cut);
    if (piece.hideSkin) covered.push(...inside.map((f) => f.v));
    if (piece.group !== "body" && inside.some((f) => f.v.some((v) => Math.hypot(P[v * 3] - gc[0], P[v * 3 + 1] - gc[1], P[v * 3 + 2] - gc[2]) < 0.06))) b.coversAnatomy = true;
  }
  for (const v of verts) {
    const spacing = smoothOf.get(v);
    if (!spacing) {
      b.refs.push(v, v, v), b.weights.push(1, 0, 0);
      continue;
    }
    const i = local.get(v)!;
    // Torso vertices of every layer share one sample set, so stacked layers move alike.
    const bind = shepard(P, isTorso(mc, v) ? torsoSamples(mc, spacing) : [...coarse.get(spacing)!, ...torsoSamples(mc, spacing)], [b.positions[i * 3], b.positions[i * 3 + 1], b.positions[i * 3 + 2]]);
    b.refs.push(...bind.refs);
    b.weights.push(...bind.weights);
    for (let axis = 0; axis < 3; axis++) offsets[i * 3 + axis] = bind.offset[axis];
  }
  b.scaleRefs = scaleRefsOf(P, verts);
  b.hides = covered.length ? mc.coveredBody(P, covered) : [];
  return b;
}

/** One vertex per grid cell (the closest to the cell centre). */
function coarseSample(P: number[], vertices: number[], spacing: number): number[] {
  const cells = new Map<string, [number, number]>();
  for (const v of vertices) {
    const k = [0, 1, 2].map((c) => Math.floor(P[v * 3 + c] / spacing));
    const d = Math.hypot(...[0, 1, 2].map((c) => P[v * 3 + c] / spacing - k[c] - 0.5));
    const key = k.join(",");
    if (!cells.has(key) || cells.get(key)![1] > d) cells.set(key, [v, d]);
  }
  return [...cells.values()].map(([v]) => v);
}

/**
 * Proxy binding of point p to the 3 nearest of `samples`: Shepard weights minus the 4th nearest's,
 * so the weights (and the offset) change continuously from point to point.
 */
function shepard(P: number[], samples: number[], p: Vec3): { refs: number[]; weights: number[]; offset: Vec3 } {
  const near = samples.map((c) => [Math.hypot(P[c * 3] - p[0], P[c * 3 + 1] - p[1], P[c * 3 + 2] - p[2]), c]).sort((x, y) => x[0] - y[0]).slice(0, 4);
  const cut = 1 / max(1e-6, near[3]?.[0] ?? 1e3) ** 2;
  const w = near.slice(0, 3).map(([d]) => max(1e-9, 1 / max(1e-6, d) ** 2 - cut));
  const sum = w.reduce((a, b) => a + b, 0);
  const refs = near.slice(0, 3).map(([, c]) => c);
  const weights = w.map((x) => x / sum);
  const offset = [0, 1, 2].map((axis) => p[axis] - refs.reduce((acc, c, k) => acc + weights[k] * P[c * 3 + axis], 0)) as Vec3;
  return { refs, weights, offset };
}
